mapper.select:
select distinct sr.id, sr.role_name, sr.role_key, sr.sort, sr.data_scope, sr.status, sr.create_time, sr.create_by, sr.update_time, sr.update_by, sr.remark from sys_role sr
left join sys_user_role sur on sr.id = sur.role_id
left join sys_user su on sur.user_id = su.id
where sr.del_flag = false

    and sr.role_name = #{req.roleName}


    and sr.role_key = #{req.roleKey}


    and sr.status = #{req.status}


    and sr.create_time >= #{req.startCreateTime}


    and sr.create_time <= #{req.endCreateTime}


    and su.id = #{req.userId}

select sr.id, sr.sort, sr.role_name, sr.role_key, sr.data_scope, sr.create_time from sys_role sr left join sys_user_role sur on sr.id = sur.role_id left join sys_user su on sur.user_id = su.id where sr.del_flag = false and sr.status = 0
and sur.user_id = #{userId}
group by sr.id, sr.sort, sr.role_name, sr.role_key, sr.data_scope, sr.create_time order by sort
